--
-- Table structure for table `md_city`
--

DROP TABLE IF EXISTS `md_city`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_city` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `city_code` varchar(64) NOT NULL COMMENT '城市编码',
  `city_name` varchar(100) NOT NULL COMMENT '城市名称',
  `province` varchar(100) DEFAULT NULL COMMENT '所属省份',
  `city_level` varchar(20) NOT NULL DEFAULT 'C' COMMENT '城市级别:A一类/B二类/C三类/SPECIAL特殊城市',
  `is_abroad` tinyint NOT NULL DEFAULT '0' COMMENT '是否境外:0否 1是',
  `sort` int NOT NULL DEFAULT '0',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL/DISABLED',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_city_code` (`tenant_id`,`city_code`),
  KEY `idx_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=945 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='城市(差旅分档)';
